def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Find 2x2 blocks, then keep only blocks that do not overlap vertically
    # with another 2x2 block in the same columns.
    blocks = []
    for r in range(h - 1):
        for c in range(w - 1):
            if all(grid[y][x] == 2
                   for y in (r, r + 1)
                   for x in (c, c + 1)):
                blocks.append((r, c))

    for r, c in blocks:
        if (r - 1, c) not in blocks and (r + 1, c) not in blocks:
            for y in (r, r + 1):
                for x in (c, c + 1):
                    out[y][x] = 8
    return out
